#!/usr/bin/env python3
"""Regenerates the addendum (sec. 5) of reports/05_selection.md from the CURRENT jsons (selection_final, mva, diag_deta, table, ensemble scores)."""
import json, numpy as np
WH = "/eos/home-r/rjiang/vbs_zh_codex_starter/p2/runs/multi_r1/wh"
r = json.load(open(f"{WH}/work/sel/selection_final.json")); m = json.load(open(f"{WH}/work/sel/mva.json")); d = json.load(open(f"{WH}/work/sel/diag_deta.json")); t = dict(np.load(f"{WH}/work/sel/table.npz")); meta = json.load(open(f"{WH}/work/sel/table_meta.json"))
y = (t["cls"] == meta["classes"]["signal"]); w = t["w"]; sc = np.mean([np.load(f"{WH}/work/sel/mva_scores_seed{s}.npy") for s in (11, 22, 33)], 0); thr = r["mva"]["choice"]["thr"]; neg = int((w < 0).sum())
def eff(lo, hi):
    mm = (t["mgg"] > lo) & (t["mgg"] < hi) & ~y; p = mm & (sc > thr); W = w[mm].sum(); e = w[p].sum()/W; er = np.sqrt((w[p]**2).sum()*(1-e)**2+(w[mm & ~p]**2).sum()*e**2)/W; return e, er
bins = [(100, 110), (110, 120), (120, 130), (130, 150), (150, 180)]; E = {b: eff(*b) for b in bins}
side = [(100, 110), (110, 120), (130, 150), (150, 180)]; sm = np.average([E[b][0] for b in side])
cb = r["cut_based"]; mv = r["mva"]; ne = r["mva_nested"]; ens = mv["choice"]
fl = "; ".join(f"{b[0]}-{b[1]}: {E[b][0]:.3f} +- {E[b][1]:.3f}" for b in bins)
txt = f"""
## 5. Addendum v2 (after the focused review, binding: reviews/wh_05_selection.md; orchestrator decisions D44/D45)
**Decisions (orchestrator defaults pending human D44/D45):** the CUT-BASED selection is the PRIMARY. The MVA is NOT adopted; it is an alternative result only. Deviation to log (SPEC section 7): section 1 read the pre-declared word "spread" as relative RMS after seeing a fold range of 19 %; that reading was post-hoc and is withdrawn (with the range reading the MVA fails the 10 % criterion). **Pre-declaration integrity:** section 0 was written in the same command that created the scan script (not committed before the scan, no independent timestamp); the selection ran on the 05a v2.1 weights before the 05a recheck conclusions were relayed; blinding itself holds (no data, expected yields only).
**Retraining trigger (D45, pre-declared now):** cuts and models are FROZEN and only re-evaluated when the v1.1 rows (F_QCD_llajj_loose, H_ggF_jj) arrive. Retraining only if the lost-lepton or the non-prompt-lepton share of the selected background b changes by more than 30 % (relative); then retrain with nested CV only. The primary (cut-based) is NOT re-decided.
**Fix 1 (m_gg leak, reduced, NOT removed):** pt1, pt2, ptgg, drgg rebuilt m_gg exactly; v2 inputs are pt1/m_gg, pt2/m_gg, ptgg/m_gg. The background m_gg sculpting is reduced but remains: background efficiency of the ensemble score cut by m_gg range (weighted MC, with MC errors): {fl}; sideband mean {sm:.3f}; the 120-130 GeV efficiency is {100*(E[(120,130)][0]/sm-1):+.0f} % relative to the sideband mean ({(E[(120,130)][0]-sm)/E[(120,130)][1]:.1f} sigma of its MC error), and the range over the other bins is {min(E[b][0] for b in side):.3f}-{max(E[b][0] for b in side):.3f} (v1 leak: 0.10-0.15 in 120-128 against 0.06-0.10 in the sidebands). Residual dependence of the score on m_gg (through mjj/mT/etc. correlations with the diphoton mass in the prompt background) means an MVA-based fit would need a sideband-validated shape; this is a further reason for D44 (alternative only).
**Fix 2 (nested threshold):** threshold and m_gg half-width chosen on 4 folds, applied to the 5th, summed: nested Z = {ne['Z']:.3f} (s {ne['s']:.3f}, b {ne['b']:.3f}, N_eff {ne['neff']:.0f}); the ensemble (non-nested) point is Z = {ens['Z']:.3f} (s {ens['s']:.3f}, b {ens['b']:.3f}, N_eff {ens['neff']:.0f}); per-seed non-nested Z {[round(x,3) for x in mv['seed_Z']]} (the first-run value 0.621 quoted earlier belonged to the previous table). MVA nested gain over the cut-based set: {100*(ne['Z']/cb['Z']-1):.0f} % (against the extended-grid diagnostic {d['Zmax']['Z']:.3f}: {100*(ne['Z']/d['Zmax']['Z']-1):.0f} %).
**Fix 3 (|deta_jj| grid edge):** the declared grid ends at |deta_jj| > 4.0 and the primary sits on the edge. Diagnostic only (declared grid kept): deta > 4.5 gives Z = {d['chosen_cuts_with_deta_4p5']['Z']:.3f} (N_eff {d['chosen_cuts_with_deta_4p5']['neff']:.0f}), deta > 5.0 gives {d['chosen_cuts_with_deta_5p0']['Z']:.3f}; the extended-grid plateau rule picks {d['plateau_choice']['cuts']} (Z {d['plateau_choice']['Z']:.3f}): the cut-based reference is under-optimised by about 5 %.
**Fix 4 (rows carried as variants for 07):** (i) H_ggF_jj not yet produced (893012 running; the loop skips a missing skim, now logged here; D38 fallback UL until v1.1); (ii) heavy flavour: nominal = factorised variant (0.055 events in PEAK for Q_aajjj), direct-row variant (0 raw rows) and UL (0.474 + 0.283) are sensitivity variants (this removes the v1 difference 0.803 vs 0.8433); (iii) V_WWa/WZa/ZZa: zero MC rows at the selection (raw N = 0), UL 0.467 at PEAK, D29 100 % PS uncertainty acts on zero events: logged deviation, UL variant in 06 sec. 5; (iv) F_QCD_llajj_loose (899916) replaces the eFake QCD part when delivered.
**Fix 5 (disclosures):** fold = (evt + 3*sid) mod 5 (the hash reduces to this because 2654435761 = 1 mod 5); evt is not unique within a sample (fakes: several rows per event): rows of one event share (evt, sid) and therefore the fold, so event-level disjointness holds. Training uses |w| ({neg} negative-weight rows in the table). Per-seed per-fold background N_eff {json.dumps({s: [round(x,1) for x in v['fold_neff_bkg']] for s,v in m['seeds'].items()})} (two folds < 30 in each seed); signal N_eff per fold {json.dumps({s: [round(x) for x in v.get('fold_neff_sig', [])] for s,v in m['seeds'].items()})}.
**Fix 6:** Barlow-Beeston (per-bin MC-stat nuisance, and with/without MC stat) is MANDATORY in 07: cut-based b = {cb['b']:.3f} has N_eff = {cb['neff']:.0f}.
"""
s = open(f"{WH}/reports/05_selection.md").read(); i = s.index("## 5. Addendum v2")
s = s[:i].rstrip("\n") + "\n" + txt + "\n**Refresh note:** after the table fix (factorised HF nominal, leak-free inputs) the pre-declared scan was re-run on the new table: the chosen cut set is unchanged ({mjj>600, |deta|>4.0, pT(gg)>75, hw 3.5}), s = %.3f, b = %.3f (was 1.793), Z = %.3f, N_eff = %.0f. Sections 1-2 above quote the first run (b = 1.793, Z = 0.434).\n**Final tables (current inputs, nominal = 05a v2.1; work/sel/selection_tables.md):**\n" % (cb["s"], cb["b"], cb["Z"], cb["neff"]) + open(f"{WH}/work/sel/selection_tables.md").read() + "\n"
sv = json.load(open(f"{WH}/work/sel/selection_v11.json")); a = sv["v1"]; b = sv["v11"]
s += f"""
## 6. v1.1 re-evaluation with the FROZEN cuts and models (loose-cut eFake sample, D45)
Table work/sel/table_v11.npz (F_QCD_llajj_loose replaces the QCD part of ZH_Zajj_eFake; EW part kept). Cut-based (frozen): s = {b['cut_based']['s']:.3f}, b = {b['cut_based']['b']:.3f} (before {a['cut_based']['b']:.3f}), Z (Eq. 1) = {b['cut_based']['Z']:.3f} (before {a['cut_based']['Z']:.3f}), b N_eff = {b['cut_based']['neff']:.0f} (before {a['cut_based']['neff']:.0f}; rel. MC {100*b['cut_based']['relmc']:.0f} %). Frozen MVA (average of the 15 models, in-sample for the training rows, ratio only): Z {a['mva_frozen_avgmodel']['Z']:.3f} -> {b['mva_frozen_avgmodel']['Z']:.3f}. **D45 trigger NOT fired** (lost-lepton share {100*sv['D45']['lost_lepton_egamma']['share_v1']:.1f} % -> {100*sv['D45']['lost_lepton_egamma']['share_v11']:.1f} %, non-prompt share {100*sv['D45']['nonprompt_lepton']['share_v1']:.2f} % -> {100*sv['D45']['nonprompt_lepton']['share_v11']:.2f} %; threshold 30 % relative): no retraining; the primary stays cut-based. H_ggF_jj: gridpack 893012 failed (D-WH-14); D38 scaled central proxy applied as a bound variant (05a sec. 12): Z0 -0.6 %, no retraining.
"""
xc = json.load(open(f"{WH}/work/v11_crosscheck.json")); u2 = xc["v11"]["all_lostlep_class"]
s += f"""**Disclosure:** in v1.1 the lost-lepton class at the selection has N_eff = {u2['neff']:.1f} ({u2['nraw']} raw rows), Y = {u2['Y']:.3f} +- {u2['stat']:.3f} ({100*u2['stat']/u2['Y']:.0f} % MC stat) and holds {100*u2['share_of_b_sumw2']:.0f} % of the sum of squared weights of b; the loose-sample per-event weight is {xc['weight_ratio_loose_to_vbs']:.0f} x that of the replaced vbs QCD rows, and its QCD part rests on {xc['v11']['loose_QCD_part']['nraw']} raw row at the selection. The b N_eff drop 135 -> 63 is entirely this. Cross-check table (vbs twin x C range against the loose direct): 05a sec. 11. The nominal is not changed (final reviewer decides).
"""
open(f"{WH}/reports/05_selection.md", "w").write(s); print("ok", fl)
